'use strict';
// ================= ROMANCING STREAM: the story. eight full origins, town talk, recruits, bosses, the curse, the endings =================
// the frame: long ago the TEN CARTRIDGES sealed THE CURSE inside the Old Stream. they got scattered, and the things the
// Curse touched are holding them. three servants keep the road to the Old Stream shut. anyone can start this. anyone can finish it.
const HOOKS = {};
async function storyHook(kind, id, room) {
  const f = HOOKS[kind + ':' + id + (room !== undefined ? ':' + room : '')]; if (f) { HOOK++; try { await f(); } finally { HOOK--; } }
  await personalEvent(kind, id, room); await recruitEvent(kind, id);
}
const ME = () => cName(GS.hero);
const once = k => { if (GS.flags[k]) return false; GS.flags[k] = 1; return true; };
const inParty = id => GS.party.includes(id);
// ---------------- the world gets older ----------------
async function worldTick() {
  const notes = [];
  if (GS.br >= 12 && once('t12')) notes.push(['THE STREAM IS GETTING LOUDER.', '', 'SOMEWHERE, THREE SERVANTS', 'OF THE CURSE WOKE UP.']);
  if (GS.er >= 3 && once('e3')) notes.push(['WORD GETS AROUND.', '', 'THE PUBS HAVE WORK NOW.', 'ASK AROUND, IN ANY TOWN.']);
  if (GS.er >= 8 && once('e8')) notes.push(['THE SHOPKEPTERS RESTOCKED.', '', 'EVERYTHING COSTS MORE.', 'EVERYTHING IS BETTER. THAT IS THE DEAL.']);
  if (GS.er >= 15 && once('e15')) notes.push(['PEOPLE STOPPED ASKING IF YOU ARE NEW.', '', 'THE WORLD HAS OPINIONS ABOUT YOU NOW.']);
  if (GS.br >= 40 && !GS.flags.court88done && GS.open.court88 && once('t40')) { delete GS.open.court88; GS.flags.court88gone = 1; if (GS.quests.appeal && GS.quests.appeal.s === 1) GS.quests.appeal.s = 3; notes.push(['COURTROOM 88 HAS ADJOURNED.', '', 'THE CASE WAS DISMISSED.', 'NOBODY WAS THERE TO HEAR IT.']); }
  if (GS.br >= 46 && !GS.flags.mirrordone && GS.open.mirror && once('t46')) { delete GS.open.mirror; GS.flags.mirrorgone = 1; notes.push(['THE MIRROR GARDEN CLOSED.', '', 'THE EMPRESS STOPPED LOOKING.']); }
  if (GS.br >= 26 && GS.quests.rookjob && GS.quests.rookjob.s === 1 && once('t26r')) notes.push(['THE PIGEONS LEFT THE ROOKERY.', '', 'THEY TOOK THE PHONE NUMBER WITH THEM.']);
  if (!GS.open[GS.loc]) GS.loc = CHARS[GS.hero].home;
  for (const n of notes) { sfx('glitch'); await showCard(n, 0, { bg: PAPER, fg: SEPIA }); }
}
