// opening fights teach, they do not kill: softer foes with no tricks, and everyone starts each one healthy
async function tutorialFight(fam, n = 1, o = {}) { for (const id of GS.party) PC(id).hp = PC(id).mhp; const foes = []; for (let i = 0; i < n; i++) { const f = monFrom(fam, o.br || 0); f.hp = f.mhp = Math.round(f.mhp * .55); f.str = Math.round(f.str * .65); f.skill = ['attack']; foes.push(f); } const r = await battle(foes, { theme: o.theme || PLACES[GS.loc].theme, easyflee: 1, intro: o.intro }); if (r === 'lose') return gameOver(); scene = fieldScene; music(PLACES[GS.loc].music); await fadeIn(.1); }
