async function personalEvent(kind, id, room) {
  if (!GS) return;
  for (const hero in PERSONAL) for (const pe of PERSONAL[hero]) {
    if (GS.hero !== hero || GS.flags[pe.id]) continue;
    if (pe.er && GS.er < pe.er) continue;
    if (pe.hook !== kind || pe.place !== id) continue;
    if (pe.hook === 'room' && pe.room !== undefined && pe.room !== room) continue;
    HOOK++;
    try { await pe.run(); GS.flags[pe.id] = 1; } finally { HOOK--; }
  }
}
